// Map Zulip emoji reaction → approval verb.
// Topic name format from approval-request: 'approval-<task_id_prefix>' OR explicit topic.
// The full task_id must be carried in the message content (the approval-request workflow
// embeds it as a hidden link or footer). For MVP we expect topic = 'approval-<full_task_id>'.
const payload = $input.first().json.body || {};
const reactionRaw = (payload.data || '').toLowerCase();
const emoji = (payload.message && payload.message.last_edit_timestamp) ? null : null; // placeholder
// Zulip outgoing-webhook for reactions: payload.trigger='reaction_add', payload.message.subject=topic, payload.data=':emoji_name:'
const topic = payload.message ? payload.message.subject : (payload.topic || '');
const senderEmail = payload.message ? payload.message.sender_email : (payload.actor || 'unknown');
let reaction = null;
if (reactionRaw.includes('thumbs_up') || reactionRaw.includes('+1') || reactionRaw.includes('check')) reaction = 'approve';
else if (reactionRaw.includes('thumbs_down') || reactionRaw.includes('-1') || reactionRaw.includes('x')) reaction = 'reject';
else if (reactionRaw.includes('pause') || reactionRaw.includes('clock') || reactionRaw.includes('hourglass')) reaction = 'defer';
if (!reaction) {
  return [{ json: { skip: true, reason: 'unrecognized reaction: ' + reactionRaw } }];
}
const taskMatch = topic.match(/approval-([a-f0-9-]{8,})/i);
if (!taskMatch) {
  return [{ json: { skip: true, reason: 'topic does not match approval-<task_id>: ' + topic } }];
}
const task_id = taskMatch[1];
// action_class / server / method are not in the reaction payload; the approval token contract
// embeds them. For MVP, this workflow signs a token over (task_id, reaction) only; errand-runner
// validates the full tuple from state.approval_request. The HMAC is the integrity check that the
// approval came from THIS n8n instance, not that the action tuple matches state.
return [{ json: { task_id, reaction, actor: senderEmail.split('@')[0] || 'rob' } }];

// HMAC contract (matches errand_runner._verify_approval_token):
//   payload = task_id|action_class|server|method|nonce
//   token   = payload + ':' + hex(hmac-sha256(LANGGRAPH_APPROVAL_SIGNING_KEY, payload))
// At reaction time we don't have action_class/server/method — those were captured when the
// approval was REQUESTED. For MVP, the approval-request workflow stashes them in a Zulip
// message footer (machine-readable) and the receive side reads them back. Until that's wired,
// we ship a placeholder tuple ('approve'/'unknown'/'unknown') and let errand-runner reject
// mismatches. That keeps the HMAC path tested end-to-end while we iterate on the lookup.
const crypto = require('crypto');
const signingKey = $env.LANGGRAPH_APPROVAL_SIGNING_KEY;
if (!signingKey) {
  throw new Error('LANGGRAPH_APPROVAL_SIGNING_KEY env var is not set on n8n; cannot mint tokens.');
}
const { task_id, reaction, actor } = $input.first().json;
const action_class = 'C';
const server = 'unknown';
const method = 'unknown';
const nonce = crypto.randomBytes(8).toString('hex');
const payload = [task_id, action_class, server, method, nonce].join('|');
const signature = crypto.createHmac('sha256', signingKey).update(payload).digest('hex');
const approval_token = payload + ':' + signature;
return [{ json: { task_id, reaction, actor, approval_token } }];
